#!/usr/bin/env python3
"""Retain actual replays of every newly retained depth-three safety finding."""
import json
import pathlib
import subprocess
import sys

root, diag, recorder = map(pathlib.Path, sys.argv[1:])
environment = json.loads((diag / 'environment.json').read_text())['environment']
executable = pathlib.Path(environment['CARGO_TARGET_DIR']) / 'debug/chaoscontrol-explore'
if not executable.is_file():
    raise SystemExit('The actually built current-source explorer is unavailable')
contracts = json.loads((diag / 'campaign-command-contracts.json').read_text())
results = []


def load(path):
    return json.loads(path.read_text())


def run(name, argv):
    out = diag / name
    subprocess.run([sys.executable, str(recorder), '--out', str(out), '--timeout', '300', '--', *argv], cwd=root)
    return load(out / 'execution.json')


def is_deep_safety(bug):
    kind = ((bug.get('assertion_identity') or {}).get('descriptor') or {}).get('kind')
    return bug.get('replay_parent_depth', 0) >= 3 and kind in ('always', 'always_or_unreachable')


for contract in contracts['campaigns']:
    identifier = contract['id']
    command = contract['command']
    directory = pathlib.Path(command[command.index('--output') + 1])
    checkpoint_path = directory / 'checkpoint.json'
    result = dict(id=identifier, checkpoint_path=str(checkpoint_path), checkpoint_present=checkpoint_path.is_file(), replays=[], complete_inventory=False, all_retained_deep_safety_findings_replayed=False)
    if checkpoint_path.is_file():
        checkpoint = load(checkpoint_path)
        retained = checkpoint.get('bugs', [])
        deep = [bug for bug in retained if is_deep_safety(bug)]
        expected_ids = {bug['bug_id'] for bug in deep}
        if len(expected_ids) != len(deep):
            raise SystemExit('Duplicate retained deep safety identity: ' + identifier)
        result.update(total_retained_findings=len(retained), retained_deep_safety_findings=len(deep), deep_safety_observed=bool(deep))
        exported = {}
        if deep:
            export = run('fresh-export-' + identifier, [str(executable), 'export-bugs', '--checkpoint', str(checkpoint_path), '--output', str(directory), '--min-replay-parent-depth', '3'])
            result['export_command_observation'] = export
            for path in sorted(directory.glob('bug_*.json')):
                bug = load(path)
                if is_deep_safety(bug):
                    if bug['bug_id'] in exported:
                        raise SystemExit('Duplicate exported deep safety identity: ' + identifier)
                    exported[bug['bug_id']] = (path, bug)
            result['complete_inventory'] = export['exit_code'] == 0 and not export['operational_timeout'] and set(exported) == expected_ids
        else:
            result['complete_inventory'] = True
        for bug_id, (path, bug) in sorted(exported.items()):
            verdict_path = directory / ('fresh-replay-verdict-bug' + str(bug_id) + '.json')
            argv = [str(executable), 'reproduce', '--kernel', command[command.index('--kernel') + 1], '--initrd', command[command.index('--initrd') + 1], '--bug', str(path)]
            for option in ['--vms', '--seed', '--bootstrap-budget', '--memory-mb', '--extra-cmdline']:
                argv.extend([option, command[command.index(option) + 1]])
            argv.extend(['--verdict-output', str(verdict_path)])
            observation = run('fresh-replay-' + identifier + '-bug' + str(bug_id), argv)
            verdict = load(verdict_path) if verdict_path.is_file() else None
            snapshot = (verdict or {}).get('snapshot', {})
            passed = observation['exit_code'] == 0 and not observation['operational_timeout'] and verdict is not None and verdict.get('schema_version') == 2 and verdict.get('replay_class') == 'snapshot_backed_reproduced' and verdict.get('reproduced') is True and verdict.get('bug_id') == bug_id and verdict.get('assertion_id') == bug['assertion_id'] and verdict.get('assertion_identity') == bug['assertion_identity'] and verdict.get('replay_parent_depth') == bug['replay_parent_depth'] and snapshot.get('status') == 'valid' and snapshot.get('present') is True and snapshot.get('digest_verified') is True and snapshot.get('reference') == bug['replay_parent_snapshot_ref']
            result['replays'].append(dict(bug_id=bug_id, parent_depth=bug['replay_parent_depth'], bug_path=str(path), parent_path=str(directory / bug['replay_parent_snapshot_ref']['path']), verdict_path=str(verdict_path), verdict=verdict, command_observation=observation, passed=passed))
        result['all_retained_deep_safety_findings_replayed'] = result['complete_inventory'] and len(result['replays']) == len(deep) and all(row['passed'] for row in result['replays'])
    results.append(result)
    summary = dict(schema='chaoscontrol.continuation-fresh-deep-replay-observations.v1', source=contracts['source'], campaigns=results, all_complete=len(results) == len(contracts['campaigns']), all_retained_deep_safety_findings_replayed=all(row['all_retained_deep_safety_findings_replayed'] for row in results), non_claims=['An empty inventory is not evidence of an observed deep safety replay.', 'The deliberate snapshot probe is not a discovered fig8 Raft defect.', 'Every retained shallow or liveness finding remains in its original checkpoint and assertion table; no host timeout is a guest bug.'])
    (diag / 'fresh-deep-replays.json').write_text(json.dumps(summary, indent=2) + '\n')
print(json.dumps(dict(all_complete=summary['all_complete'], all_retained_deep_safety_findings_replayed=summary['all_retained_deep_safety_findings_replayed'], campaigns=[{key: row.get(key) for key in ['id', 'total_retained_findings', 'retained_deep_safety_findings', 'all_retained_deep_safety_findings_replayed']} for row in results]), indent=2))
raise SystemExit(0 if summary['all_complete'] and summary['all_retained_deep_safety_findings_replayed'] else 1)
